{
  "items": [
    {
      "title": "German Longitudinal Election Study (GLES), 2009–2017",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "A major German political science dataset covering federal elections, political parties, voting behavior, political attitudes, and electoral campaigns. Includes studies associated with the 2013 and 2017 Bundestag elections, making it particularly relevant for examining Germany's political system and party competition during the 2010s."
    },
    {
      "title": "ParlGov: Parliaments and Governments Database",
      "url_or_doi": "https://www.parlgov.org/data-info/",
      "justification": "Provides comparative data on political parties, national elections, parliamentary representation, and government cabinets. Includes Germany throughout the 2010s, allowing researchers to analyze coalition governments, party composition, electoral outcomes, and changes in parliamentary politics."
    },
    {
      "title": "GERDA: The German Election Database",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "A comprehensive database of German federal, state, and municipal election results. Covers elections throughout the 2010s and provides geographically harmonized information on political party vote shares. Particularly useful for studying regional political differences, local government, and electoral developments across Germany."
    },
    {
      "title": "GERDA: The German Election Database — Scientific Data",
      "url_or_doi": "https://doi.org/10.1038/s41597-025-04811-5",
      "justification": "Research publication documenting the German Election Database, which combines municipal, state, and federal election results. Its historical coverage includes the 2010s, enabling systematic analysis of electoral competition, political representation, and relationships between different levels of government."
    },
    {
      "title": "German Federal and State Election Results Since 1946 — Konrad Adenauer Stiftung",
      "url_or_doi": "https://www.kas.de/en/web/wahlanalysen-und-gesellschaftsstudien/election-results-representative-election-statistics",
      "justification": "Provides historical election datasets for Germany and its federal states, including elections throughout 2010–2019. Contains party vote shares, voter turnout, parliamentary seat distributions, and demographic voting statistics. Useful for investigating party systems, electoral participation, and changes in political representation."
    },
    {
      "title": "Small-Area Global Elections (SAGE): Germany",
      "url_or_doi": "https://sage-elections.com/germany/",
      "justification": "Provides detailed geographic election results for Germany, including the 2013 and 2017 Bundestag elections. Includes polling-station-level results and aggregated geographic datasets. Particularly suitable for analyzing local electoral geography, political party support, and regional voting patterns during the 2010s."
    },
    {
      "title": "German Longitudinal Election Study — Historical Data Archive",
      "url_or_doi": "https://wzb.eu/en/research/completed-research-programs/democracy-and-democratization/downloads",
      "justification": "The WZB Berlin Social Science Center provides access information for historical German election research datasets, including longitudinal surveys, candidate studies, election campaign panels, and media content data. Particularly relevant to the 2009, 2013, and 2017 federal elections and the study of German political organizations and democratic processes."
    },
    {
      "title": "Research Data Center Elections at GESIS",
      "url_or_doi": "https://www.konsortswd.de/en/services/research/all-datacentres/fdz-wahlen/",
      "justification": "Provides access to extensive German election research collections, including the German Longitudinal Election Study, Politbarometer, DeutschlandTREND, and German state election studies. These resources include observations from 2010–2019 and support research on political institutions, voter preferences, party identification, and government evaluations."
    },
    {
      "title": "Comparative Agendas Project — Germany",
      "url_or_doi": "https://compagendas.la.utexas.edu/project/germany/datasets",
      "justification": "Contains datasets examining German political and governmental policy agendas, including government speeches, political party manifestos, and other indicators of policy priorities. Relevant for investigating political decision-making, government policy priorities, party competition, and the evolution of political agendas during the 2010s. Coverage varies by individual dataset."
    },
    {
      "title": "German Federal Election Results and Historical Electoral Data — Wahlzahlen",
      "url_or_doi": "https://wahlzahlen.de/datenbasis",
      "justification": "Combines historical German federal election results, political party data, electoral constituencies, parliamentary representatives, and polling information. Includes information relevant to the 2013 and 2017 Bundestag elections, supporting analysis of Germany's electoral system, parliamentary composition, and political party development."
    }
  ]
}
